#!/usr/bin/perl
# Minimal HTTP GET forced through a given interface (SO_BINDTODEVICE), e.g. uesimtun0.
# usage: perl ue-http-get.pl <ifname> <host> [port] [path]
use strict; use Socket;
my ($if,$host,$port,$path)=@ARGV; $port||=80; $path||="/";
socket(my $s, PF_INET, SOCK_STREAM, getprotobyname('tcp')) or die "socket: $!";
setsockopt($s, SOL_SOCKET, 25, pack("Z*",$if)) or die "SO_BINDTODEVICE: $!";   # 25 = SO_BINDTODEVICE
$SIG{ALRM}=sub{die "timeout\n"}; alarm 10;
connect($s, sockaddr_in($port, inet_aton($host))) or die "connect: $!";
my ($lport,$laddr)=sockaddr_in(getsockname($s));
print STDERR "# local ".inet_ntoa($laddr).":$lport via $if -> $host:$port\n";
syswrite($s,"GET $path HTTP/1.0\r\nHost: $host\r\nConnection: close\r\n\r\n");
my $buf; while (sysread($s,$buf,4096)) { print $buf }
EOF
